SELECT cmsprovider_2.hcpcs_description AS hcpcs_description,   CAST(cmsprovider_2.nppes_provider_zip AS BIGINT) AS nppes_provider_zip,   AVG(CAST(cmsprovider_2.average_submitted_chrg_amt AS double precision)) AS avg:average_submitted_chrg_amt:ok FROM cmsprovider_2 WHERE ((cmsprovider_2.hcpcs_description IN ('Removal of joint lining from two or more knee joint compartments using an endoscope', 'Removal of knee cap', 'Removal of knee joint covering')) AND (cmsprovider_2.nppes_provider_state = 'CA')) GROUP BY cmsprovider_2.hcpcs_description,   cmsprovider_2.nppes_provider_zip,   cmsprovider_2.nppes_provider_zip;
